def count_odd(limit):
    N = 0
    for x in range(limit):
        for y in range(limit):
            val = (x + y) * (x + y + 1) // 2 + x
            if val % 2 == 1:
                N += 1
    return N

print(count_odd(100))

def count_odd_for_s(s, limit):
    count = 0
    for x in range(s + 1):
        y = s - x
        if 0 <= x < limit and 0 <= y < limit:
            val = s * (s + 1) // 2 + x
            if val % 2 == 1:
                count += 1
    return count

def N_for_limit(limit):
    N = 0
    for s in range(2 * limit - 1):
        N += count_odd_for_s(s, limit)
    return N

print(N_for_limit(100))

def check_f1_range(limit):
    vals = []
    for x in range(limit):
        for y in range(limit):
            vals.append((x + y) * (x + y + 1) // 2 + x)
    return min(vals), max(vals), sorted(vals)

print(check_f1_range(100))

def check_gaps(limit):
    vals = set()
    for x in range(limit):
        for y in range(limit):
            vals.add((x + y) * (x + y + 1) // 2 + x)

    max_val = max(vals)
    gaps = 0
    for i in range(max_val + 1):
        if i not in vals:
            gaps += 1
    return gaps

print(check_gaps(100))

