def count_odd_f(limit, mode='x'):
    N = 0
    for s in range(2 * limit - 1):
        h_s = s * (s + 1) // 2
        x_min = max(0, s - (limit - 1))
        x_max = min(s, limit - 1)
        for x in range(x_min, x_max + 1):
            if mode == 'x':
                val = h_s + x
            else:
                val = h_s + (s - x)
            if val % 2 == 1:
                N += 1
    return N

print(f"n=100, mode=x: {count_odd_f(100, 'x')}")
print(f"n=100, mode=y: {count_odd_f(100, 'y')}")
